TLM.f("Tempora/Quad6-4rm1",{"officium":"De missa chrismatis","rule":["Gloria","Credo","Prefatio=Chrismatis","celebranda aut de missa chrismatis aut missa in coena Domini","prelude"],"sections":{"Introitus":[{"k":"ref","la":"Exodi 30, 25 et 31"},{"k":"text","la":"Fácies unctiónis óleum, et fíliis Israel dices: Hoc óleum unctiónis sanctum erit mihi in generatiónes vestras."},{"k":"ref","la":"Ps 88, 2"},{"k":"text","la":"Grátias Dómini in aetérnum cantábo; per omnes generatiónes annuntiábo fidelitátem tuam."},{"k":"ref","la":"Exodi 30, 25 et 31"},{"k":"text","la":"Fácies unctiónis óleum, et fíliis Israel dices: Hoc óleum unctiónis sanctum erit mihi in generatiónes vestras."},{"k":"rubric","la":"Tempore Passionis non dicitur Gloria Patri ad Antiphonam ad Introitum"}],"Oratio":[{"k":"text","la":"Dómine, Deus, qui in regenerándis plébibus tuis ministério úteris sacerdótum; tríbue nobis perseverántem in tua voluntáte famulátum; ut dono grátiæ tuæ, in diébus nostris, et méritis et número sacrátus tibi pópulus augeátur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Jacóbi Apóstoli."},{"k":"ref","la":"Jc 5:13-16"},{"k":"text","la":"Fratres: Tristátur áliquis vestrum? Oret. Æquo ánimo est? Psallat. Infirmátur quis in vobis? Indúcat presbýteros ecclésiæ, et orent super eum, ungéntes eum óleo in nómine Dómini; et orátio fídei salvábit infírmum, et alleviábit eum Dóminus; et si in peccátis sit, remitténtur ei. Confitémini ergo altérutrum peccáta vestra, et oráte pro ínvicem ut salvémini; multum enim valet deprecátio justi assídua."}],"Graduale":[{"k":"ref","la":"Ps 27, 7-8"},{"k":"text","la":"In Deo confísum est cor meum, et adiútus sum; ídeo exsúltat cor meum, et cántico meo laudo eum. Dóminus robur est pópulo suo, et presídium salútis uncto suo."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Marcum."},{"k":"ref","la":"Marc 6:7-13"},{"k":"text","la":"In illo témpore: Vocávit Jesus duódecim, et coepit eos míttere binos, et dabat illis potestátem spirítuum immundórum. Et præcépit eis, ne quid tóllerent in via, nisi virgam tantum; non peram, non panem, neque in zona æs, sed calceátos sandáliis, et ne indueréntur duábus túnicis. Et dicébat eis: « Quocúmque introiéritis in domum, illic manéte, donec exeátis inde; et quicúmque non recéperint vos, nec audíerint vos, exeúntes inde, excútite púlverem de pédibus vestris, in testimónium illis ». Et exeúntes prædicábant ut pæniténtiam ágerent; et dæmónia multa ejiciébant, et ungébant óleo multos ægros, et sanábant."}],"Offertorium":[{"k":"ref","la":"Ps 44, 8"},{"k":"text","la":"Díligis iustítiam et odísti iniquitátem; proptérea unxit te Deus, Deus tuus, óleo laetítiae."}],"Secreta":[{"k":"text","la":"Hujus sacrifícii poténtia, Dómine, quǽsumus, et vetustátem nostram cleménter abstérgat, et novitátem nobis áugeat et salútem."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Marc. 6:12-13"},{"k":"text","la":"Prædicábant Apóstoli ut pæniténtiam ágerent, et ungébant óleo multos ægros, et sanábant."}],"Postcommunio":[{"k":"text","la":"Præsta, quǽsumus, Dómine: ut, sicut de prætéritis ad nova transímus; ita, vetustáte depósita, sanctificátis méntibus innovémur."},{"k":"macro","name":"Per Dominum"}],"Prelude":[{"k":"rubric","la":"Benedictio olei catechumenorum et infirmorum, et confectio sacri chrismatis peraguntur secundum ordinem in Pontificali Romano descriptum."}]},"hr":{"7d5c928442ce4fbd":{"t":"Izl 30, 25 i 31, Ps 88, 2\n(Izl 30, 25 i 31) Pripravi ulje za pomazanje i reci sinovima Izraelovim: Ovo ulje neka bude meni posvećeno u svim pokoljenjima vašim. (Ps 88, 2) O milostima Gospodnjim uvijek ću pjevati. Kroz sva pokoljenja naviještat ću vjernost tvoju. (Izl 30, 25 i 31) Pripravi ulje za pomazanje i reci sinovima Izraelovim: Ovo ulje neka bude meni posvećeno u svim pokoljenjima vašim. [u vremenu Muke ne govori se Slava Ocu u sklopu Ulazne pjesme]"},"da9f2ab986b7d165":{"t":"<i>Pomolimo se</i>.\nGospodine Bože, koji po svećeničkoj službi preporađaš svoj puk, daj da ti u skladu s tvojom voljom ustrajno služimo, da se po daru tvoje milosti umnoži u naše dane i zaslugama i brojem tebi posvećeni narod.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pomolimo se! Prignite ponizno glave svoje pred Bogom! Daj nam, molimo. Gospodine, ustrajno službovanje u Tvojoj volji, da se u naše dane puk, koji Tebi služi, sve više množi i zaslugama i brojem, po G. n.","knRef":"Kniewald 1942, str. 202–203 (snimka 102) (OCR)"},"cbcee81988f93d77":{"t":"Jak 5, 13-16\nČitanje Poslanice bl. Jakova apostola. Braćo: Predragi, ako tko između vas trpi. neka moli; ako je raspoložen, neka pjeva; ako je pak bolestan, neka dozove svećenike Crkve, koji neka mole nad njim i pomažu ga uljem u ime Gospodnje. Molitva vjere izliječit će bolesnoga. Podignut će ga Gospodin. Ako je u grijesima, oprostit će mu se. Dakle, priznavajte jedan drugome svoje grijehe i molite jedan za drugoga, da se spasite, jer mnogo može ustrajna molitva pravednika!"},"a297df8840f822c0":{"t":"Ps 27, 7-8\nU Boga se pouzdalo srce moje i on mi je pomogao. Zato srce moje kliče od radosti i hvalim ga pjesmom svojom. Gospodin je snaga naroda svoga i zaštita spasenja pomazanika svoga."},"b6bb80bda8b6f108":{"t":"Mk 6, 7-13\nSlijedi sveto Evanđelje po Marku. U ono vrijeme: Dozva Isus dvanaestoricu te ih poče slati dva po dva dajući im vlast nad nečistim dusima. I zapovjedi im da na put ne nose ništa osim štapa: ni kruha, ni torbe, ni novaca o pojasu, nego da nose samo sandale i da ne oblače dviju haljina. I govoraše im: Kad uđete gdje u kuću, u njoj ostanite dok ne odete odande. Ako vas gdje ne prime te vas ne poslušaju, iziđite odande i otresite prah ispod svojih nogu njima za svjedočanstvo. Otišavši, propovijedali su obraćenje, izgonili mnoge zloduhe i mnoge su nemoćnike mazali uljem i oni su ozdravljali."},"7294ce7667cfbc01":{"t":"Ps 44, 8\nTi ljubiš pravdu a mrziš nepravdu. Radi toga te je pomazao Bog, Bog tvoj, uljem radosti."},"b81076df7c941cbc":{"t":"Molimo, Gospodine, da moć ove žrtve blago odstrani ono što je ostarjelo u nama, poveća nam novi život i spasenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"5059b19b24db081e":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno smjerno moliti blagost tvoju da za one koji se imaju obnoviti u spasonosnoj kupelji krštenja potvrdiš stvorenje krizme za otajstvo savršenog spasenja i života; da po svetom mazanju nestane onoga što je pokvareno u prvom rođenju pa da posvećeni hram svakog pojedinca zamiriše mirisom nevina i tebi prijatnog života tako da budu uzdignuti u kraljevskoj, svećeničkoj i proročkoj časti, te da po tvojoj otajstvenoj odredbi obuku odjeću nepropadljive službe po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju ti se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"19957b47f021b320":{"t":"Mk 6, 12-13\nApostoli su propovijedali obraćenje, mnoge su nemoćnike mazali uljem i oni su ozdravljali."},"3b4a209f319e1794":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, Gospodine, kao što od starog prelazimo na novo, da se tako odbacivši što je staro obnovimo posvećenim duhom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
